import random,subprocess
random.seed(4)
def spark(pts,col,w=54,h=16,fill=True):
    n=len(pts);mn,mx=min(pts),max(pts)
    xy=[(i*w/(n-1),h-2-(p-mn)/(mx-mn+1e-9)*(h-4)) for i,p in enumerate(pts)]
    d=' '.join(f'{x:.1f},{y:.1f}' for x,y in xy)
    area=f'<polygon points="0,{h} {d} {w},{h}" fill="url(#g{col[1:]})" opacity=".35"/>' if fill else ''
    lx,ly=xy[-1]
    return f'<svg width="{w}" height="{h}" viewBox="0 0 {w} {h}"><defs><linearGradient id="g{col[1:]}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="{col}"/><stop offset="1" stop-color="{col}" stop-opacity="0"/></linearGradient></defs>{area}<polyline points="{d}" fill="none" stroke="{col}" stroke-width="1.3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="{lx:.1f}" cy="{ly:.1f}" r="1.8" fill="{col}"/></svg>'
