ph=[8.02,8.0,8.03,8.07,8.1,8.13,8.15,8.16,8.15,8.14,8.13,8.14]
def bubbles():
    s=''
    for i in range(14):
        x=random.uniform(5,95);y=random.uniform(8,92);r=random.uniform(1.2,3.6)
        s+=f'<i class="bub" style="left:{x:.0f}%;top:{y:.0f}%;width:{r*2:.1f}px;height:{r*2:.1f}px"></i>'
    return s
